package com.example.digitalnotam.scenario.rwylim;
import com.example.digitalnotam.baseline.*;import com.example.digitalnotam.domain.Notam;import com.example.digitalnotam.xml.CommonDigitalNotamBuilder;import org.w3c.dom.*;import java.util.*;
final class RwyLimScenarioValidator {
 void validate(Document d,Notam n,BaselineRunwayCatalog.ResolvedTarget target){Element ets=CommonDigitalNotamBuilder.one(d,CommonDigitalNotamBuilder.EVENT,"EventTimeSlice");expected(ets,"scenario","RWY.LIM");expected(ets,"version","2.0");NodeList fs=d.getElementsByTagNameNS(CommonDigitalNotamBuilder.AIXM,"RunwayDirection");if(fs.getLength()!=target.directions().size())throw new IllegalArgumentException("RunwayDirection TEMPDELTA 数量不正确");Set<String> expected=target.directions().stream().map(BaselineRunwayCatalog.RunwayDirectionBaseline::uuid).collect(java.util.stream.Collectors.toSet()),actual=new HashSet<>(),ids=new HashSet<>();String event=((Element)d.getElementsByTagNameNS(CommonDigitalNotamBuilder.EVENT,"Event").item(0)).getAttributeNS(CommonDigitalNotamBuilder.GML,"id").replaceFirst("^uuid\\.","");for(int i=0;i<fs.getLength();i++){Element f=(Element)fs.item(i);actual.add(f.getAttributeNS(CommonDigitalNotamBuilder.GML,"id").replaceFirst("^uuid\\.",""));Element s=BaselineAirportHeliportCatalog.first(f,"RunwayDirectionTimeSlice");expected(s,"interpretation","TEMPDELTA");int normal=0,eventCount=0;for(Element w:BaselineAirportHeliportCatalog.directChildren(s,"availability")){String status=BaselineAirportHeliportCatalog.text(w,"operationalStatus");if("NORMAL".equals(status))normal++;if(Set.of("LIMITED","OTHER:EXTENDED").contains(status)){eventCount++;Element a=BaselineAirportHeliportCatalog.first(w,"ManoeuvringAreaAvailability");NodeList usages=a.getElementsByTagNameNS(CommonDigitalNotamBuilder.AIXM,"ManoeuvringAreaUsage");if(usages.getLength()<1)throw new IllegalArgumentException("RWY.LIM 必须包含 ManoeuvringAreaUsage");for(int j=0;j<usages.getLength();j++){Element u=(Element)usages.item(j);if(BaselineAirportHeliportCatalog.text(u,"operation").isBlank())throw new IllegalArgumentException("每个 Usage 必须包含 operation");String type=BaselineAirportHeliportCatalog.text(u,"type");if(!("PERMIT".equals(type)?"OTHER:EXTENDED":"LIMITED").equals(status))throw new IllegalArgumentException("Usage type 与 operationalStatus 不一致");}}}if(normal==0||eventCount!=1)throw new IllegalArgumentException("每个方向必须包含基线 NORMAL 和一个事件 availability");Element link=BaselineAirportHeliportCatalog.first(f,"theEvent");if(link==null||!("urn:uuid:"+event).equals(link.getAttributeNS(CommonDigitalNotamBuilder.XLINK,"href")))throw new IllegalArgumentException("RunwayDirection 未链接当前 Event");}if(!actual.equals(expected))throw new IllegalArgumentException("受影响方向与输入不一致");NodeList all=d.getElementsByTagNameNS("*","*");for(int i=0;i<all.getLength();i++){Element e=(Element)all.item(i);if(e.hasAttributeNS(CommonDigitalNotamBuilder.GML,"id")&&!ids.add(e.getAttributeNS(CommonDigitalNotamBuilder.GML,"id")))throw new IllegalArgumentException("重复 gml:id");}}
 private static void expected(Element e,String l,String v){if(!v.equals(BaselineAirportHeliportCatalog.text(e,l)))throw new IllegalArgumentException(l+" 必须为 "+v);}
}
